use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantLoginProviderSourceAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantLoginProviderSourceAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getSource returns null on a freshly created holder.
     */
    public function testSourceNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithTenantLoginProviderSourceAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isSourceAssigned());
        $this->assertNull($holder->getSource());
    }
}
class ImplWithTenantLoginProviderSourceAttributeHolderUnitTest
{
    use TenantLoginProviderSourceAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedSourceRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultSource();
    }
}
